import{_ as t,o as n,c,a5 as o}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"08 — Gói Cước, Thanh Toán SePay (VietQR) & Quản Trị Ví AI Credit (Subscription, Billing & AI Credit)","description":"","frontmatter":{},"headers":[],"relativePath":"ba/08-subscription-billing.md","filePath":"ba/08-subscription-billing.md"}'),a={name:"ba/08-subscription-billing.md"};function d(i,e,r,s,g,l){return n(),c("div",null,[...e[0]||(e[0]=[o('<h1 id="_08-—-goi-cuoc-thanh-toan-sepay-vietqr-quan-tri-vi-ai-credit-subscription-billing-ai-credit" tabindex="-1">08 — Gói Cước, Thanh Toán SePay (VietQR) &amp; Quản Trị Ví AI Credit (Subscription, Billing &amp; AI Credit) <a class="header-anchor" href="#_08-—-goi-cuoc-thanh-toan-sepay-vietqr-quan-tri-vi-ai-credit-subscription-billing-ai-credit" aria-label="Permalink to &quot;08 — Gói Cước, Thanh Toán SePay (VietQR) &amp; Quản Trị Ví AI Credit (Subscription, Billing &amp; AI Credit)&quot;">​</a></h1><p>&gt; [&lt;&lt; 07 - Publishing &amp; Social](file:///D:/ProjectCode/BrandHub/brandhub-infrastructure/docs/ba/07-publishing-social-collaborator.md) | [Overview](file:///D:/ProjectCode/BrandHub/brandhub-infrastructure/docs/ba/00-overview.md) | [Tiếp: 09 - Admin Management &gt;&gt;](file:///D:/ProjectCode/BrandHub/brandhub-infrastructure/docs/ba/09-admin-management.md) &gt; &gt; <strong>Phạm vi FR chuẩn</strong>: <strong>Mục <code>3.9 Subscription &amp; Billing</code> — 6 FR (<code>3.9.1</code> – <code>3.9.6</code>)</strong> | <code>UC-122</code> – <code>UC-127</code>. &gt; Tuân thủ tuyệt đối <code>AGENTS.md</code> (<strong>Không có Downgrade Plan</strong>, <strong>Chỉ dùng cổng thanh toán SePay / PayOS VietQR</strong>) và kiến trúc hợp nhất <strong>Ví AI Credit cấp Agency + Trần Ngân sách cấp Workspace (<code>workspace-credit-unification</code>)</strong>.</p><hr><h2 id="_1-bang-tong-hop-6-yeu-cau-chuc-nang-chuan-3-9-1-–-3-9-6" tabindex="-1">1. Bảng Tổng hợp 6 Yêu cầu Chức năng Chuẩn (<code>3.9.1</code> – <code>3.9.6</code>) <a class="header-anchor" href="#_1-bang-tong-hop-6-yeu-cau-chuc-nang-chuan-3-9-1-–-3-9-6" aria-label="Permalink to &quot;1. Bảng Tổng hợp 6 Yêu cầu Chức năng Chuẩn (`3.9.1` – `3.9.6`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Mã FR</th><th style="text-align:center;">Mã UC</th><th style="text-align:left;">Tên Chức năng Chuẩn (Atomic CRUD FR)</th><th style="text-align:left;">Actors / Roles Chuẩn</th><th style="text-align:left;">Mô tả Nghiệp vụ Cốt lõi</th></tr></thead><tbody><tr><td style="text-align:center;"><strong><code>3.9.1</code></strong></td><td style="text-align:center;"><code>UC-122</code></td><td style="text-align:left;"><strong>Upgrade Plan</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:left;">Xem bảng so sánh các gói dịch vụ (<code>Basic</code>, <code>Plus</code> / <code>Pro</code>, <code>Enterprise</code>) và khởi tạo đơn nâng cấp hoặc gia hạn gói cước cho <code>Agency</code> / <code>Personal Hub</code>.</td></tr><tr><td style="text-align:center;"><strong><code>3.9.2</code></strong></td><td style="text-align:center;"><code>UC-123</code></td><td style="text-align:left;"><strong>Make Payment (SePay)</strong></td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:left;">Thực hiện thanh toán đơn hàng nâng cấp gói cước hoặc mua gói thông qua mã <strong>VietQR động (SePay / PayOS)</strong>; hệ thống đối soát tự động qua Webhook và kích hoạt quyền lợi tức thì.</td></tr><tr><td style="text-align:center;"><strong><code>3.9.3</code></strong></td><td style="text-align:center;"><code>UC-124</code></td><td style="text-align:left;"><strong>View Invoice History</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Admin</code></td><td style="text-align:left;">Xem danh sách lịch sử hóa đơn và giao dịch thanh toán (<code>PENDING</code>, <code>PAID</code>, <code>EXPIRED</code>, <code>CANCELLED</code>), xem chi tiết và xuất chứng từ hóa đơn.</td></tr><tr><td style="text-align:center;"><strong><code>3.9.4</code></strong></td><td style="text-align:center;"><code>UC-125</code></td><td style="text-align:left;"><strong>View AI Credit Tracking</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:left;">Theo dõi số dư ví AI Credit của <code>Agency</code>, mức tiêu thụ và phần đang tạm giữ (<code>workspaceUsed</code> + <code>workspaceHeld</code>) của từng <code>Workspace</code>, cùng lịch sử giao dịch chi tiết theo từng tác vụ AI.</td></tr><tr><td style="text-align:center;"><strong><code>3.9.5</code></strong></td><td style="text-align:center;"><code>UC-126</code></td><td style="text-align:left;"><strong>Buy Credit</strong></td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:left;">Mua bổ sung gói AI Credit (credit mua thêm không bị hết hạn cuối chu kỳ) thông qua luồng thanh toán SePay / PayOS.</td></tr><tr><td style="text-align:center;"><strong><code>3.9.6</code></strong></td><td style="text-align:center;"><code>UC-127</code></td><td style="text-align:left;"><strong>Set Credit</strong></td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:left;">Thiết lập, điều chỉnh hoặc gỡ bỏ <strong>trần ngân sách AI Credit cho từng Workspace (<code>workspaceLimit</code>)</strong> thuộc <code>Agency</code> (<code>PUT /api/v1/agencies/{agencyId}/credit/workspaces/{workspaceId}/limit</code>).</td></tr></tbody></table><hr><h2 id="_2-co-cau-goi-cuoc-subscription-plans-quyen-loi-đinh-muc" tabindex="-1">2. Cơ cấu Gói Cước (<code>Subscription Plans</code>) &amp; Quyền lợi Định mức <a class="header-anchor" href="#_2-co-cau-goi-cuoc-subscription-plans-quyen-loi-đinh-muc" aria-label="Permalink to &quot;2. Cơ cấu Gói Cước (`Subscription Plans`) &amp; Quyền lợi Định mức&quot;">​</a></h2><p>Hệ thống cung cấp 3 hạng gói cước chuẩn áp dụng chung cho cả <code>Agency</code> B2B và <code>Personal Hub</code> cá nhân:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Quyền lợi / Định mức</th><th style="text-align:center;"><strong><code>Basic</code> (Gói Mặc định / Miễn phí)</strong></th><th style="text-align:center;"><strong><code>Plus</code> / <code>Pro</code> (Gói Chuyên nghiệp)</strong></th><th style="text-align:center;"><strong><code>Enterprise</code> (Gói Doanh nghiệp / Quy mô lớn)</strong></th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Cách kích hoạt</strong></td><td style="text-align:center;">Tự động cấp ngay khi tạo <code>Agency</code> hoặc <code>Personal Studio</code></td><td style="text-align:center;">Nâng cấp/Gia hạn qua SePay (<code>3.9.1</code>, <code>3.9.2</code>)</td><td style="text-align:center;">Nâng cấp/Gia hạn qua SePay (<code>3.9.1</code>, <code>3.9.2</code>)</td></tr><tr><td style="text-align:left;"><strong>Định mức AI Credit cấp theo chu kỳ (<code>Plan Credit</code>)</strong></td><td style="text-align:center;">Theo cấu hình gói của <code>Admin</code> (<code>3.10.7</code>)</td><td style="text-align:center;">Theo cấu hình gói của <code>Admin</code> + ưu đãi giao diện <code>Plus</code> (<code>agency-plus-style</code>)</td><td style="text-align:center;">Định mức cao nhất theo cấu hình của <code>Admin</code></td></tr><tr><td style="text-align:left;"><strong>Định mức Gửi Email Newsletter (<code>newsletter.quota.*</code>)</strong></td><td style="text-align:center;"><strong>1.000 email / tháng / agency</strong></td><td style="text-align:center;"><strong>10.000 email / tháng / agency</strong></td><td style="text-align:center;"><strong>50.000 email / tháng / agency</strong></td></tr><tr><td style="text-align:left;"><strong>Hỗ trợ Nâng cấp &amp; Gia hạn (<code>Renewal</code>)</strong></td><td style="text-align:center;">Có thể nâng cấp lên <code>Plus</code> hoặc <code>Enterprise</code> bất kỳ lúc nào</td><td style="text-align:center;">Hỗ trợ gia hạn sớm (<code>agency-plus-renewal</code>) hoặc nâng cấp lên <code>Enterprise</code></td><td style="text-align:center;">Hỗ trợ gia hạn theo chu kỳ tháng/năm</td></tr></tbody></table><p>&gt; <strong>Quy tắc bất biến theo <code>AGENTS.md</code></strong>: Hệ thống <strong>không có chức năng Hạ cấp gói (<code>Downgrade Plan</code>)</strong>.</p><hr><h2 id="_3-luong-thanh-toan-tu-đong-qua-sepay-payos-vietqr-—-3-9-1-3-9-3" tabindex="-1">3. Luồng Thanh Toán Tự Động Qua SePay / PayOS (VietQR — <code>3.9.1</code>..<code>3.9.3</code>) <a class="header-anchor" href="#_3-luong-thanh-toan-tu-đong-qua-sepay-payos-vietqr-—-3-9-1-3-9-3" aria-label="Permalink to &quot;3. Luồng Thanh Toán Tự Động Qua SePay / PayOS (VietQR — `3.9.1`..`3.9.3`)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Owner chọn Nâng cấp gói (3.9.1) hoặc Mua thêm Credit (3.9.5)]</span></span>\n<span class="line"><span>       │</span></span>\n<span class="line"><span>       ▼</span></span>\n<span class="line"><span>[Backend tạo Order + Invoice (status = PENDING) kèm mã tham chiếu thanh toán duy nhất]</span></span>\n<span class="line"><span>       │</span></span>\n<span class="line"><span>       ▼</span></span>\n<span class="line"><span>[Frontend hiển thị mã VietQR động (Số tài khoản, Ngân hàng, Số tiền chính xác, Nội dung chuyển khoản)]</span></span>\n<span class="line"><span>       │</span></span>\n<span class="line"><span>       ├──(Người dùng quét QR trên App Ngân hàng)──▶ [Cổng SePay / PayOS nhận biến động số dư]</span></span>\n<span class="line"><span>       │                                                       │</span></span>\n<span class="line"><span>       │                                                       ▼</span></span>\n<span class="line"><span>       │                                    [Webhook gọi về Backend (xác thực chữ ký &amp; chống trùng lặp Idempotent)]</span></span>\n<span class="line"><span>       │                                                       │</span></span>\n<span class="line"><span>       ▼                                                       ▼</span></span>\n<span class="line"><span>[Trạng thái Invoice chuyển sang PAID] ──▶ [Cấp gói Subscription mới + Ghi nhận Plan Credit / Purchased Credit vào Ví Agency]</span></span></code></pre></div><ul><li><strong>Chống ghi nhận trùng (<code>Idempotency</code>)</strong>: Một giao dịch thanh toán hoặc callback Webhook từ SePay bị gửi lặp nhiều lần tuyệt đối không bao giờ cộng tiền hay kích hoạt gói 2 lần.</li><li><strong>Lịch sử Hóa đơn (<code>3.9.3 View Invoice History</code>)</strong>: <ul><li><code>Owner</code> xem toàn bộ hóa đơn của <code>Agency</code> / <code>Personal Hub</code> mình sở hữu tại <code>/agency/billing</code>.</li><li><code>Admin</code> xem và đối soát toàn bộ hóa đơn trên toàn hệ thống kèm thống kê doanh thu tại <code>/admin/revenue</code>.</li></ul></li></ul><hr><h2 id="_4-kien-truc-hop-nhat-vi-ai-credit-tran-ngan-sach-workspace-3-9-4-–-3-9-6" tabindex="-1">4. Kiến trúc Hợp nhất Ví AI Credit &amp; Trần Ngân sách Workspace (<code>3.9.4</code> – <code>3.9.6</code>) <a class="header-anchor" href="#_4-kien-truc-hop-nhat-vi-ai-credit-tran-ngan-sach-workspace-3-9-4-–-3-9-6" aria-label="Permalink to &quot;4. Kiến trúc Hợp nhất Ví AI Credit &amp; Trần Ngân sách Workspace (`3.9.4` – `3.9.6`)&quot;">​</a></h2><p>Theo đặc tả chuẩn đã chốt tại <code>docs/feature/workspace-credit-unification/spec.md</code>:</p><h3 id="_4-1-mot-vi-tong-cap-agency-single-agency-wallet-hai-nguon-credit" tabindex="-1">4.1. Một Ví Tổng cấp Agency (<code>Single Agency Wallet</code>) &amp; Hai Nguồn Credit <a class="header-anchor" href="#_4-1-mot-vi-tong-cap-agency-single-agency-wallet-hai-nguon-credit" aria-label="Permalink to &quot;4.1. Một Ví Tổng cấp Agency (`Single Agency Wallet`) &amp; Hai Nguồn Credit&quot;">​</a></h3><ul><li>Mỗi <code>Agency</code> (bao gồm cả <code>Personal Hub</code>) có <strong>duy nhất 1 ví <code>agency_credit_wallets</code></strong> là nguồn tiền thực tế cho mọi Workspace trực thuộc.</li><li>Trong ví chia làm 2 lớp số dư (<code>Credit Grants</code>): <ol><li><strong><code>Plan Credit</code> (Credit định kỳ theo gói)</strong>: Được cấp khi kích hoạt/gia hạn gói cước và làm mới theo chu kỳ gói.</li><li><strong><code>Purchased Credit</code> (Credit mua thêm — Non-expiring)</strong>: Không bị hết hạn khi kết thúc chu kỳ gói; ngay cả khi gói trả phí đã hết hạn, người dùng vẫn được phép tiêu số <code>Purchased Credit</code> còn lại.</li></ol></li><li><strong>Thứ tự ưu tiên khấu trừ</strong>: Hệ thống luôn trừ <strong><code>Plan Credit</code> trước</strong>, khi hết <code>Plan Credit</code> mới trừ sang <strong><code>Purchased Credit</code></strong>.</li></ul><h3 id="_4-2-tran-ngan-sach-cap-workspace-workspace-credit-cap-—-3-9-6-set-credit" tabindex="-1">4.2. Trần Ngân sách cấp Workspace (<code>Workspace Credit Cap</code> — <code>3.9.6 Set Credit</code>) <a class="header-anchor" href="#_4-2-tran-ngan-sach-cap-workspace-workspace-credit-cap-—-3-9-6-set-credit" aria-label="Permalink to &quot;4.2. Trần Ngân sách cấp Workspace (`Workspace Credit Cap` — `3.9.6 Set Credit`)&quot;">​</a></h3><ul><li>Hệ thống <strong>đã bãi bỏ hoàn toàn hạn mức cá nhân theo từng thành viên</strong> (các lệnh ghi hạn mức cá nhân cũ trả mã <code>410 Gone — CREDIT_PERSONAL_LIMIT_RETIRED</code>).</li><li>Thay vào đó, <code>Owner</code> kiểm soát ngân sách theo từng <strong><code>Workspace</code></strong> (<code>PUT /api/v1/agencies/{agencyId}/credit/workspaces/{workspaceId}/limit</code> với <code>{ cap: number | null, expectedRevision: number }</code>): <ul><li><strong><code>cap = null</code> (Không giới hạn riêng — Unlimited)</strong>: Workspace được phép sử dụng tự do miễn là ví tổng của Agency còn số dư khả dụng.</li><li><strong><code>cap = N</code> (<code>N &gt; 0</code>)</strong>: Tổng lượng credit đã dùng (<code>workspaceUsed</code>) cộng lượng đang tạm giữ (<code>workspaceHeld</code>) của mọi thành viên (<code>Owner</code>, <code>Manager</code>, <code>Creator</code>) trong Workspace đó trong chu kỳ hiện tại không được vượt quá <code>N</code>.</li><li><strong><code>cap = 0</code></strong>: Khóa hoàn toàn các tác vụ AI tính phí trong Workspace đó (các tác vụ AI miễn phí vẫn hoạt động bình thường).</li></ul></li><li><strong>Phân quyền hiển thị</strong>: <ul><li><code>Owner</code> xem và chỉnh sửa được hạn mức của tất cả các Workspace trong Agency.</li><li><code>Manager</code> và <code>Creator</code> chỉ xem được hạn mức và mức sử dụng (<code>workspaceLimit</code>, <code>workspaceUsed</code>, <code>workspaceHeld</code>) của chính các Workspace mà họ đang tham gia, không lộ số dư riêng tư của các Workspace khác.</li></ul></li></ul><h3 id="_4-3-quy-trinh-tam-giu-quyet-toan-nguyen-tu-reserve-→-settle-release" tabindex="-1">4.3. Quy trình Tạm giữ &amp; Quyết toán Nguyên tử (<code>Reserve → Settle / Release</code>) <a class="header-anchor" href="#_4-3-quy-trinh-tam-giu-quyet-toan-nguyen-tu-reserve-→-settle-release" aria-label="Permalink to &quot;4.3. Quy trình Tạm giữ &amp; Quyết toán Nguyên tử (`Reserve → Settle / Release`)&quot;">​</a></h3><ol><li><strong>Kiểm tra bảng giá cố định của Admin</strong>: <ul><li>Chỉ đúng <strong>4 nhóm tác vụ</strong> sử dụng bảng giá của Admin (<code>3.10.10</code>–<code>3.10.12</code>): <ol><li><code>CONTENT_GENERATE</code> (Sinh bài viết / caption mới — <code>3.7.6</code>)</li><li><code>AMBASSADOR_GENERATE</code> (Sinh đại sứ thương hiệu — <code>3.7.7</code>)</li><li><code>COMMERCIAL_IMAGE</code> (Sinh ảnh thương mại — <code>3.7.9</code>)</li><li><code>VIDEO_GENERATE</code> (Sinh video AI — <code>3.7.11</code>)</li></ol></li><li>Các tác vụ <code>CAPTION_VARIANTS</code> (tinh chỉnh biến thể), <code>HASHTAG_GENERATE</code> (<code>3.7.14</code>), <code>CHARACTER_SHEET</code> luôn miễn phí (<code>unit_credits = 0</code>, <code>rate_version = FREE_V1</code>).</li></ul></li><li><strong>Tạm giữ (<code>Reserve / HOLD</code>)</strong>: Trước khi gọi sang nhà cung cấp AI (không bao giờ gọi HTTP bên ngoài bên trong transaction tài chính), hệ thống khóa ví Agency và kiểm tra đồng thời số dư khả dụng của Agency và trần của Workspace, sau đó tạo bản ghi tạm giữ.</li><li><strong>Quyết toán (<code>Settle / Release</code>)</strong>: Khi AI trả kết quả thành công, hệ thống chốt trừ credit (<code>SETTLE</code>); nếu AI thất bại, hệ thống giải phóng khoản tạm giữ (<code>RELEASE</code>) để người dùng không bao giờ bị mất oan credit.</li></ol>',23)])])}const u=t(a,[["render",d]]);export{p as __pageData,u as default};
